<script setup lang="ts">
import {computed,onUnmounted,ref,shallowRef} from 'vue';
import AnnotationEditor from '../components/AnnotationEditor.vue';
import MaterialPreview from '../components/MaterialPreview.vue';
import type {AiReviewContext,ReviewItem} from '../types/ai-review';
const props=defineProps<{context:AiReviewContext}>(),s=shallowRef(props.context.snapshot()),a=props.context.actions;
const stop=props.context.subscribe(value=>{s.value=value});onUnmounted(stop);
const inspecting=ref('');
const inspected=computed(()=>s.value.items.find(row=>row.image_id===inspecting.value));
const locked=computed(()=>s.value.busy||s.value.loading||!!s.value.pending||s.value.ambiguity.scanning||s.value.ambiguity.saving);
const filters=[['all','全部候选'],['clean_boxes','有框 · 无歧义'],['ambiguous','有歧义'],['with_boxes','全部有框'],['zero','零框'],['empty','空目标'],['unreviewed','尚未审核'],['remaining','剩余可审核'],['failed','生成失败'],['edited','已有草稿'],['committed','已正式入库'],['transferred','已转池'],['blocked','流转受阻'],['rejected','已拒绝'],['low','低置信度'],['hard','难样本']];
function selectable(row:ReviewItem){return row.selectable&&!row.gt_committed&&row.status!=='failed'&&(!row.review_state||row.review_state==='active')}
function media(row:ReviewItem){return {...row,id:row.image_id,filename:row.filename||row.image_id}}
function value(event:Event){return (event.target as HTMLInputElement).value}
function diagnosis(event:MouseEvent,id:string){a.diagnostics(event.currentTarget as HTMLButtonElement,id)}
function stateName(row:ReviewItem){return row.gt_committed?'已同意 · 正式入库':row.status==='failed'?'生成失败':row.review_state==='transferred'?'已转入负样本池':row.review_state==='blocked'?'流转受阻':row.manual_review_required?'跨标签重叠 · 待核对':row.draft_revision?'候选草稿已保存':row.accepted===false?'已拒绝':row.accepted===true?'已采用候选':'待人工审核'}
</script>
<template>
<AnnotationEditor v-if="s.edit&&context.editor" :key="s.edit.imageId" :context="context.editor" :snapshot="s.edit"/>
<section v-else class="review-workbench" aria-label="AI 候选审核工作台">
  <header class="review-header"><div><p class="eyebrow">AI 候选审核</p><h1>核对候选，确认所选素材</h1><p class="identity">项目 {{ s.projectId }} · 任务 {{ s.taskId }} <span v-if="s.status">· {{ s.status }}</span></p></div><div class="actions"><button :disabled="locked" @click="a.legacy()">使用原工作台</button><button :disabled="locked" @click="a.close()">关闭审核</button></div></header>
  <div v-if="s.pending" class="notice" role="status">操作 {{ s.pending.request_id }} 的结果尚待核验，请先查询原回执。<button @click="a.lookup()">核验提交回执</button></div>
  <div v-if="s.error" class="notice error" role="alert">{{ s.error }} <button :disabled="locked" @click="a.reload()">重新读取</button></div>
  <div class="review-body">
    <aside class="filters"><h2>审核范围</h2><nav aria-label="候选筛选"><button v-for="[key,name] in filters" :key="key" :disabled="locked" :aria-pressed="s.filter===key" @click="a.filter(key)">{{ name }}<span v-if="s.summary[key]!=null">{{ s.summary[key] }}</span></button></nav><p class="hint">零框仅表示候选结果。正式负样本资格仍须人工确认。</p><button :disabled="locked" @click="a.resumeTransfer()">恢复原转池操作</button></aside>
    <main class="results"><div class="toolbar"><div class="actions"><button :disabled="locked" @click="a.pageSelect(true)">选择本页可操作项</button><button :disabled="locked" @click="a.filtered()">选择全部筛选结果</button><button :disabled="locked" @click="a.clear()">清除选择</button></div><button :disabled="locked" @click="a.reload()">刷新</button></div>
      <div v-if="s.selection.id" class="frozen" role="status">服务器冻结 {{ s.selection.frozenCount??s.selection.count }} 张 · 排除 {{ s.selection.excludedCount??0 }} 张 · 当前已选 {{ s.selection.count }} 张</div>
      <section v-if="s.filter==='ambiguous'" class="ambiguity"><h2>人工消歧</h2><div class="actions"><label>处理方式<select :value="s.ambiguity.mode" :disabled="locked" @change="a.ambiguityMode(value($event))"><option value="auto">自动保留一个框</option><option value="manual">指定正式标签</option></select></label><label v-if="s.ambiguity.mode==='manual'">保留标签<select :value="s.ambiguity.label" :disabled="locked" @change="a.ambiguityLabel(value($event))"><option value="">请选择标签</option><option v-for="label in s.labels" :key="label.code" :value="label.code">{{ label.display_name||label.code }}</option></select></label><label>IoU 阈值<input type="number" min="0.5" max="1" step="0.01" :value="s.ambiguity.threshold" :disabled="locked" @change="a.ambiguityThreshold(value($event))"></label><button :disabled="locked||!s.selection.count" @click="a.ambiguityPreview()">预检已选范围</button></div><p class="hint">仅预检可安全处理的冲突；自动保留规则不代表类别判断正确。</p><p v-if="s.ambiguity.scanning" role="status">正在逐页预检…</p><div v-if="s.ambiguity.preview"><p>预检 {{ s.ambiguity.preview.scanned }} / {{ s.ambiguity.preview.total }} 张，可处理 {{ s.ambiguity.preview.actionCount }} 张，跳过 {{ s.ambiguity.preview.skippedCount }} 张。</p><details v-if="s.ambiguity.preview.actions.length"><summary>查看处理影响（最多预览 100 张）</summary><div v-for="row in s.ambiguity.preview.actions" :key="row.id"><p>{{ row.name }} · 将删除 {{ row.removed }} 个冲突框 · 保留 {{ row.keptLabel||'原规则确认标签' }}</p><p v-for="(box,index) in row.removedBoxes||[]" :key="index">{{ box.label }} · [{{ box.x1 }}, {{ box.y1 }}, {{ box.x2 }}, {{ box.y2 }}]</p></div></details><details v-if="s.ambiguity.preview.skipped.length"><summary>查看跳过原因</summary><p v-for="(row,index) in s.ambiguity.preview.skipped.slice(0,50)" :key="index">{{ row.name }} · {{ row.reason }}</p></details><button class="primary" :disabled="locked||!s.ambiguity.preview.actions.length" @click="a.ambiguityApply()">确认消歧并正式入库</button></div><p v-if="s.ambiguity.result" role="status">{{ s.ambiguity.result }}</p></section>
      <p class="page-meta">当前筛选 {{ s.total }} 张 · 第 {{ Math.floor(s.offset/Math.max(1,s.limit))+1 }} 页 <span v-if="s.loading">· 正在读取…</span></p>
      <div class="candidate-grid" :aria-busy="s.loading"><article v-for="row in s.items" :key="row.image_id" class="candidate" :class="{selected:row.selected,committed:row.gt_committed}"><MaterialPreview :image="media(row)" :project-id="s.projectId" :boxes="row.boxes"/><div class="candidate-copy"><label class="candidate-title"><input type="checkbox" :checked="row.selected" :disabled="locked||!selectable(row)" @change="a.toggle(row.image_id,($event.target as HTMLInputElement).checked)"><strong>{{ row.filename||row.image_id }}</strong></label><p class="candidate-state">{{ stateName(row) }}</p><p class="hint">{{ row.box_count??row.boxes?.length??0 }} 个候选框<span v-if="row.draft_revision"> · 草稿版本 {{ row.draft_revision }}</span></p><p v-if="row.error" class="error-text">{{ row.error_code }} {{ row.error }}</p><div class="actions"><button @click="inspecting=inspecting===row.image_id?'':row.image_id">查看详情</button><button :disabled="locked||!selectable(row)" @click="a.edit(row.image_id)">编辑候选框</button></div><div class="actions decisions" v-if="selectable(row)"><button :disabled="locked||row.manual_review_required&&!row.draft_revision" :aria-pressed="row.accepted===true" @click="a.decision(row.image_id,true)">采用候选</button><button :disabled="locked" :aria-pressed="row.accepted===false" @click="a.decision(row.image_id,false)">拒绝候选</button></div></div></article></div>
      <p v-if="!s.items.length&&!s.loading" class="empty">当前筛选没有候选图片。</p><div class="pagination"><button :disabled="locked||s.offset<=0" @click="a.page(-1)">上一页</button><span>{{ s.offset+Math.min(1,s.items.length) }}–{{ s.offset+s.items.length }} / {{ s.total }}</span><button :disabled="locked||s.offset+s.limit>=s.total" @click="a.page(1)">下一页</button></div>
    </main>
    <aside v-if="inspected" class="inspector"><div class="actions"><h2>当前图检查</h2><button @click="inspecting=''">收起详情</button></div><MaterialPreview :image="media(inspected)" :project-id="s.projectId" :boxes="inspected.boxes"/><button @click="a.preview(inspected.image_id)">原图放大与平移</button><h3>{{ inspected.filename||inspected.image_id }}</h3><p>{{ stateName(inspected) }}</p><p class="hint">当前框为有界只读预览，完整编辑使用原标注组件。</p><details v-if="inspected.conflicts?.length"><summary>原跨标签冲突证据</summary><p v-for="(conflict,index) in inspected.conflicts" :key="index">{{ conflict.labels.join(' / ') }} · IoU {{ conflict.iou }}</p></details><details><summary>当前候选框与置信度（最多 32 框）</summary><p v-for="(box,index) in inspected.boxes||[]" :key="index">{{ box.label }} · 置信度 {{ box.confidence??'未提供' }} · [{{ box.x1 }}, {{ box.y1 }}, {{ box.x2 }}, {{ box.y2 }}]</p></details><details><summary>原始候选框预览</summary><MaterialPreview :image="media(inspected)" :project-id="s.projectId" :boxes="inspected.original_boxes"/></details><button @click="diagnosis($event,inspected.image_id)">查看原标注诊断</button><button v-if="inspected.review_state==='transferred'||inspected.review_state==='blocked'" :disabled="locked||!inspected.review_operation_id" @click="a.transferReceipt(inspected.review_operation_id!)">查看原转池回执</button></aside>
  </div>
  <section id="ai60TransferPanel" hidden v-once></section>
  <footer class="review-footer"><div><strong>已选 {{ s.selection.count }} 张</strong><p>仅处理本次明确选择，正式入库需再次确认。</p></div><div class="actions"><button :disabled="locked||!s.selection.count" @click="a.openTransfer()">转入负样本池</button><button class="primary" :disabled="locked||!s.selection.count||s.filter==='ambiguous'" @click="a.approve()">确认入库已选 {{ s.selection.count }} 张</button></div></footer>
</section>
</template>
<style scoped>
.review-workbench{position:fixed;inset:8px;z-index:1100;background:#fafafa;color:#222;border:1px solid #ddd;border-radius:12px;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 12px 60px #0002;font-size:13px}.review-workbench *{box-sizing:border-box}.review-header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:18px 22px;border-bottom:1px solid #ddd;background:#fff}.eyebrow{font-size:11px;letter-spacing:.12em;color:#777;margin:0 0 4px}.review-header h1{font-size:20px;margin:0}.identity{font-size:12px;color:#666;overflow-wrap:anywhere;margin:7px 0 0}.actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}button,select,input[type=number]{font:inherit;border:1px solid #ccc;border-radius:6px;background:#fff;min-height:36px;padding:7px 11px;color:#333;max-width:100%}button{cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #333;outline-offset:2px}button[aria-pressed=true]{background:#e9e9e9;border-color:#555}.primary{background:#252525;color:white;border-color:#252525}.review-body{display:flex;min-height:0;flex:1;overflow:auto}.filters{width:180px;flex-shrink:0;padding:18px 12px;background:#f4f4f4;border-right:1px solid #ddd}.filters h2,.ambiguity h2,.inspector h2{font-size:14px;margin:0 0 12px}.filters nav{display:grid;gap:4px}.filters nav button{display:flex;justify-content:space-between;border-color:transparent;background:transparent;text-align:left}.filters nav button[aria-pressed=true]{background:#fff;border-color:#ccc;font-weight:600}.filters nav span{color:#777}.results{flex:1;min-width:0;padding:16px 20px}.toolbar{display:flex;justify-content:space-between;gap:10px;margin-bottom:12px}.candidate-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:14px}.candidate{background:white;border:1px solid #ddd;border-radius:8px;overflow:hidden;min-width:0}.candidate.selected{border-color:#333;box-shadow:0 0 0 1px #333}.candidate.committed .candidate-state{font-weight:600}.candidate-copy{padding:12px}.candidate-title{display:flex;gap:9px;align-items:flex-start;overflow-wrap:anywhere;line-height:1.5}.candidate-title input{margin-top:3px;flex-shrink:0}.candidate-title strong{font-size:13px}.candidate-state{margin:9px 0 5px;font-size:12px}.hint{color:#777;font-size:12px;line-height:1.6}.candidate-copy .actions button{font-size:12px;padding:5px 8px}.decisions{border-top:1px solid #eee;padding-top:9px;margin-top:9px}.error-text,.error{color:#9a2929}.notice{padding:10px 20px;border-bottom:1px solid #ddd;background:#f6f3ed;overflow-wrap:anywhere}.notice button{margin-left:10px}.frozen{padding:10px 12px;border:1px solid #ccc;border-radius:6px;margin-bottom:12px;background:#eee}.ambiguity{padding:14px;border:1px solid #ccc;border-radius:8px;margin-bottom:14px;background:#fff}.ambiguity label{display:grid;gap:5px;font-size:12px}.ambiguity input{width:100px}.ambiguity details p{overflow-wrap:anywhere}.page-meta{color:#777;font-size:12px}.pagination{display:flex;align-items:center;justify-content:center;gap:16px;margin:22px 0 8px;color:#666}.empty{text-align:center;padding:55px;color:#777}.inspector{width:320px;flex-shrink:0;border-left:1px solid #ddd;padding:16px;background:#fff;overflow-wrap:anywhere}.inspector h3{font-size:14px}.inspector>.actions{justify-content:space-between}.inspector>button{margin-top:12px}.review-footer{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-shrink:0;padding:13px 22px;background:#fff;border-top:1px solid #ddd}.review-footer p{margin:5px 0 0;color:#777;font-size:12px}#ai60TransferPanel{position:absolute;inset:85px 14px 85px auto;width:min(460px,calc(100% - 28px));overflow:auto;padding:20px;background:#fff;border:1px solid #bbb;box-shadow:0 12px 35px #0003;z-index:4}.candidate :deep(.material-media){border-radius:0}.candidate :deep(.media-world img){height:auto;background:#efefef}@media(max-width:1100px){.inspector{widt